package com.ecopulse.service; import com.ecopulse.dto.AuthDtos; import com.ecopulse.model.User; import com.ecopulse.repository.UserRepository; import com.ecopulse.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; @Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} public AuthDtos.AuthResponse login(AuthDtos.Login req){ User u=users.findByEmail(req.email()).orElseThrow(()->new IllegalArgumentException("Invalid email or password")); if(!encoder.matches(req.password(),u.passwordHash))throw new IllegalArgumentException("Invalid email or password"); return new AuthDtos.AuthResponse(jwt.generate(u.email),u.email,u.role.name()); } }
